-- V5__create_messages.sql
-- ─────────────────────────────────────────────────────────────────────────────
-- Messages table.
--
-- Sequence numbers:
--   (conversation_id, seq) is UNIQUE — enforces total order per conversation.
--   seq is allocated by the conversation row UPDATE, never by MAX(seq)+1.
--   MAX(seq)+1 is unsafe: two concurrent readers both see MAX=5, both try
--   seq=6, one fails with a unique violation.
--
-- Idempotency:
--   (sender_id, client_msg_id) is UNIQUE.
--   client_msg_id is generated by the CLIENT before sending.
--   If a retry arrives after a successful commit, the INSERT hits this
--   constraint and the server returns the already-committed message.
--   The database constraint is the correctness mechanism — not application logic.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE TABLE messages (
    id              UUID        NOT NULL DEFAULT gen_random_uuid(),
    conversation_id UUID        NOT NULL REFERENCES conversations(id),
    seq             BIGINT      NOT NULL,
    sender_id       UUID        NOT NULL REFERENCES users(id),
    client_msg_id   UUID        NOT NULL,
    body            TEXT        NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT pk_messages           PRIMARY KEY (id),
    CONSTRAINT uq_messages_conv_seq  UNIQUE (conversation_id, seq),
    CONSTRAINT uq_messages_idem      UNIQUE (sender_id, client_msg_id)
);

-- Primary pagination index: keyset query
--   WHERE conversation_id = ? AND seq < :cursor ORDER BY seq DESC LIMIT ?
-- PostgreSQL seeks directly to the cursor position — O(LIMIT), not O(table size).
CREATE INDEX idx_messages_conv_seq
    ON messages (conversation_id, seq DESC);

-- Supports idempotency fast-path check:
--   SELECT * FROM messages WHERE sender_id = ? AND client_msg_id = ?
CREATE INDEX idx_messages_sender_idem
    ON messages (sender_id, client_msg_id);
